// Async server component that fetches user-specific data at request time
// This component should be wrapped in <Suspense> by the parent
export default async function UserDashboard() {
  // Fetch user preferences - no 'use cache' since this is request-specific data
  // Using relative URL with base for server-side fetch
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3000';
  const res = await fetch(`${baseUrl}/api/user/preferences`, {
    cache: 'no-store' // Ensure fresh data on each request
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>User preferences: {JSON.stringify(preferences)}</p>
    </div>
  );
}

